),
info as (
select isnull(old.defect,new.defect) defect
, isnull(old.collecter,new.collecter) collecter 
, isnull(new.don_gia_moi,old.DON_GIA_CU) upricem
,upricekg
,m2kg
,kg2m
from DON_GIA_MOI new
full outer join infomation old on new.defect =old.defect and new.collecter = old.collecter
where old.defect is not null 
),
infoWeight0 as (
select 
defect,
collecter as matname,
rtrim(ltrim(case when collecter like '%Forming%' then ' (-) ' 
			when collecter like '%Etching%' then ' (+) '
			when collecter like '%Coatingroll%' then 
				case 
				when collecter like '%(-)%'
				then
				'(-)'				
				else
				'(+)'
				end
			 else collecter end)) as collecter,
right(rtrim(ltrim( collecter )),3) as size,
'(8%)' as size1,
'(7%)' as size2,
cast (upricem as float) as upricem,
cast (upricekg as float) as upricekg,
cast (m2kg as float) as m2kg,
cast (kg2m as float) as kg2m
from info
)
select * from infoWeight0
)